package com.jbrempresa.backend.entity;
import jakarta.persistence.*;import java.time.LocalDateTime;import java.time.LocalTime;
@Entity @Table(name="recursos_agendables",uniqueConstraints=@UniqueConstraint(name="uk_recurso_agendable",columnNames={"emp_id","rag_tip","rag_ref_id"}))
public class RecursoAgendable{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="rag_id") private Long ragId; @Column(name="emp_id",nullable=false) private Long empId; @Column(name="rag_tip",nullable=false,length=20) private String ragTip; @Column(name="rag_ref_id",nullable=false) private Long ragRefId; @Column(name="rag_nom",nullable=false,length=200) private String ragNom; @Column(name="rag_cap",nullable=false) private Integer ragCap; @Column(name="rag_mar_pre",nullable=false) private Integer ragMarPre; @Column(name="rag_mar_pos",nullable=false) private Integer ragMarPos; @Column(name="rag_hor_vis",nullable=false) private LocalTime ragHorVis; @Column(name="rag_usu_mov",nullable=false,length=100) private String ragUsuMov; @Column(name="rag_fec_mov",nullable=false) private LocalDateTime ragFecMov; @Column(name="rag_act",nullable=false) private Boolean ragAct;
 public Long getRagId(){return ragId;}public void setRagId(Long v){ragId=v;}public Long getEmpId(){return empId;}public void setEmpId(Long v){empId=v;}public String getRagTip(){return ragTip;}public void setRagTip(String v){ragTip=v;}public Long getRagRefId(){return ragRefId;}public void setRagRefId(Long v){ragRefId=v;}public String getRagNom(){return ragNom;}public void setRagNom(String v){ragNom=v;}public Integer getRagCap(){return ragCap;}public void setRagCap(Integer v){ragCap=v;}public Integer getRagMarPre(){return ragMarPre;}public void setRagMarPre(Integer v){ragMarPre=v;}public Integer getRagMarPos(){return ragMarPos;}public void setRagMarPos(Integer v){ragMarPos=v;}public LocalTime getRagHorVis(){return ragHorVis;}public void setRagHorVis(LocalTime v){ragHorVis=v;}public String getRagUsuMov(){return ragUsuMov;}public void setRagUsuMov(String v){ragUsuMov=v;}public LocalDateTime getRagFecMov(){return ragFecMov;}public void setRagFecMov(LocalDateTime v){ragFecMov=v;}public Boolean getRagAct(){return ragAct;}public void setRagAct(Boolean v){ragAct=v;}
}
